MangaFonts.setLoader(async id=>{const r=await chrome.runtime.sendMessage({type:'font',id});if(!r?.ok)throw Error(r?.error||'글꼴을 불러오지 못했습니다.');return r.value;});
const fontFields=new Map();
for(const [role,title] of Object.entries(MangaFonts.roles)){
 const row=document.createElement('div');row.className='font-policy-row';
 const label=document.createElement('label');label.textContent=title;label.className='font-policy-choice';const select=document.createElement('select');select.id='font-'+role;select.append(new Option('자동','auto'),new Option('기본 글꼴','default'));label.append(select);
 const boldLabel=document.createElement('label'),bold=document.createElement('input');bold.type='checkbox';bold.id='bold-'+role;boldLabel.className='font-policy-bold';boldLabel.append(bold,' 볼드 사용');row.append(label,boldLabel);document.getElementById('font-policy').append(row);const preview=MangaFontPreview.attach(select,()=>({region:{type:role==='impact'?'effect':'text',fontStyle:{role},fontChoice:select.value==='auto'?role:select.value,fontWeight:bold.checked?700:400,translation:'오늘은 어떤 이야기가 펼쳐질까?'}}));bold.addEventListener('change',preview.update);fontFields.set(role,{select,bold,preview});
}
(async()=>{const r=await chrome.runtime.sendMessage({type:'settings'});const policy=MangaFonts.normalizePolicy(r.value.fontPolicy);for(const [role,{select,bold,preview}]of fontFields){select.value=policy[role].font;bold.checked=policy[role].bold;preview.update();}for(const [k,v]of Object.entries(r.value)){const el=document.getElementById(k);if(el)el.type==='checkbox'?el.checked=v:el.value=v;}})();
document.querySelector('form').onsubmit=async e=>{e.preventDefault();const s={};for(const id of ['server','token','target','selector','captureFallback']){const el=document.getElementById(id);s[id]=el.type==='checkbox'?el.checked:el.value.trim();}try{const url=new URL(s.server);if(!['http:','https:'].includes(url.protocol))throw Error();s.server=url.href.replace(/\/$/,'');if(['127.0.0.1','localhost'].includes(url.hostname)&&url.port==='8793'&&!s.token)delete s.token;s.fontPolicy=MangaFonts.normalizePolicy(Object.fromEntries([...fontFields].map(([role,{select,bold}])=>[role,{font:select.value,bold:bold.checked}])));await chrome.storage.local.set(s);document.querySelector('output').textContent=' 저장했습니다.';}catch{document.querySelector('output').textContent=' 서버 주소를 확인하세요.';}};
